INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25801, 'Acts 1:5', 'Acts', 1, 5, '&nbsp;يحيىٰ به په اوبو بپتسمه ورکوله خو په يو څو ورځو کښې به تاسو ته په روحُ القُدس بپتسمه درکړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25802, 'Acts 1:6', 'Acts', 1, 6, '&nbsp;نو کله چې هغوئ يو ځائ راجمع وُو هغوئ د هغۀ نه تپوس وکړو چې، ”مالِکه، ولې دا هغه وخت دے چې تۀ به د بنى اِسرائيلو بادشاهى بيا قائمه کړې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25803, 'Acts 1:7', 'Acts', 1, 7, '&nbsp;عيسىٰ جواب ورکړو چې، ”دا ستاسو کار نۀ دے چې د هغه وختونو او تاريخونو په حقله پوهه شئ کوم چې زما پلار په خپل اختيار مقرر کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25804, 'Acts 1:8', 'Acts', 1, 8, '&nbsp;خو تاسو ته به د روحُ القُدس په نازلېدو طاقت درکړے شى او تاسو به په يروشلم کښې او په ټوله يهوديه او سامريه کښې او د دُنيا تر بله سره زما ګواهان يئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25805, 'Acts 1:9', 'Acts', 1, 9, '&nbsp;کله چې هغۀ دا وفرمائيل او هغوئ لا ورته کتل، چې هغه پورته کړے شو او يوه وريځ راغله او هغه يې د هغوئ د سترګو نه پناه کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25806, 'Acts 1:10', 'Acts', 1, 10, '&nbsp;کله چې هغه آسمان ته بره روان وو او مريدانو آسمان ته نېغ نېغ کتل نو ناګهانه دوه سړى په سپينو جامو کښې د هغوئ په خوا کښې ودرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25807, 'Acts 1:11', 'Acts', 1, 11, '&nbsp;هغوئ ووئيل چې، ”اے د ګليل خلقو، تاسو دلته ولې ولاړ يئ او بره آسمان ته ګورئ؟ دغه عيسىٰ څوک چې ستاسو نه آسمان ته بوتلے شو، هغه به هم په دې طريقه واپس راشى څنګه چې تاسو هغه آسمان ته په تلو وليدو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25808, 'Acts 1:12', 'Acts', 1, 12, '&nbsp;بيا هغوئ د زيتُونو د غرۀ نه يروشلم ته واپس شول کوم چې يروشلم ته نزدې دے او د يروشلم نه تقريباً يو کيلوميټر لرې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25809, 'Acts 1:13', 'Acts', 1, 13, '&nbsp;کله چې هغوئ راورسېدل نو هغوئ هغه بالاخانې ته لاړل چرته چې هغوئ دېره وُو. څوک چې هلته موجود وو هغوئ کښې پطروس، يوحنا، يعقوب، اندرياس، فيليپوس، توما، برتلماۍ، متى، يعقوب د حلفئ زوئ، شمعون ننګيالے او يهوداه د يعقوب زوئ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25810, 'Acts 1:14', 'Acts', 1, 14, '&nbsp;هغوئ ټول په يوه مخه په دُعا سر وُو او د هغوئ سره ښځې هم وې چې په کښې مريم د عيسىٰ مور او د هغۀ وروڼه هم شامل وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25811, 'Acts 1:15', 'Acts', 1, 15, '&nbsp;په دغو ورځو کښې پطروس د ايماندارانو په مينځ کښې ودرېدو چې دا ټوله ډله تقريباً په شمېر کښې شپږ شلې وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25812, 'Acts 1:16', 'Acts', 1, 16, '&nbsp;او وې وئيل، ”دوستانو، هغه پېشګويانې چې په صحيفو کښې ليکلى دى ضرور به پوره شى کومې چې د داؤد په خولۀ روحُ القُدس د يهوداه په حقله کړې وې چې هغه به د عيسىٰ د ګرفتارونکو دپاره مُخبر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25813, 'Acts 1:17', 'Acts', 1, 17, '&nbsp;هغه زمونږ د قبيلې نه يو وو او په دې خِدمت کښې زمونږ سره ملګرے وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25814, 'Acts 1:18', 'Acts', 1, 18, '&nbsp;د خپلې مخبرۍ د قيمت په بدله کښې، يهوداه يو پټے واخستو او هلته سر د لاندې راپرېوتو، خېټه يې وشلېده او ټولې کولمې يې بهر راووتلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25815, 'Acts 1:19', 'Acts', 1, 19, '&nbsp;په يروشلم کښې هر چا ته د دې خبرې پته ولګېده نو هغوئ په هغه پټى په خپله ژبه کښې حقلدما نوم کېښودو، چې مطلب يې د وينې پټے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25816, 'Acts 1:20', 'Acts', 1, 20, '&nbsp;او پطروس ووئيل چې، ”په زبور کښې دا ليکلى دى چې، د هغۀ کور دې وران شى او داسې څوک دې پاتې نۀ شى چې په هغې کښې اوسى. او د هغۀ د مشرۍ مقام دې نورو خلقو ته حواله شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25817, 'Acts 1:21', 'Acts', 1, 21, '&nbsp;نو په کار دے چې يو سړے د يهوداه په ځائ مقرر کړو د چا چې زمونږ سره د مالِک عيسىٰ د خِدمت په ټول وخت کښې راشه درشه وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25818, 'Acts 1:22', 'Acts', 1, 22, '&nbsp;د يحيىٰ د بپتسمې نه تر هغه وخته پورې چې هغه زمونږ نه پورته کړے شو. نو چې مونږ څوک منتخب کړو هغه به مونږ سره د عيسىٰ د بيا ژوندى کېدو ګواه وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25819, 'Acts 1:23', 'Acts', 1, 23, '&nbsp;نو هغوئ دوه کسان خوښ کړل، يوسف چې په برسبا مشهور وو او يوستوس هم ورته وئيلے شو او دوېم متياس وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25820, 'Acts 1:24', 'Acts', 1, 24, '&nbsp;بيا هغوئ دُعا وکړه او وې وئيل چې، ”اے مالِکه، تۀ د ټولو د زړونو نه خبر يې، مونږ ته دا وښايه چې په دوئ کښې تا کوم يو غوره کړے دے', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25821, 'Acts 1:25', 'Acts', 1, 25, '&nbsp;چې دا خِدمت او رسالت سمبال کړى کوم چې يهوداه پرېښودو او هغه هلته لاړو چرته چې هغۀ ته تلل په کار وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25822, 'Acts 1:26', 'Acts', 1, 26, '&nbsp;بيا هغوئ خسڼے واچولو او هغه د متياس په نوم راوختلو. نو بيا هغه د يوولسو رسولانو سره شامل شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25823, 'Acts 2:1', 'Acts', 2, 1, '&nbsp;د فسحې اختر نه وروسته د پنځوسمې ورځ لمانځلو دپاره ايمانداران ټول په يو ځائ راجمع شوى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25824, 'Acts 2:2', 'Acts', 2, 2, '&nbsp;ناګهانه د آسمان نه د تېز باد په شان آواز راغلو او په هغه ټول کور کښې خور شو چرته چې هغوئ ناست وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25825, 'Acts 2:3', 'Acts', 2, 3, '&nbsp;او هغوئ د اور په شان ژبې وليدلې چې په خپلو کښې جدا شوې، او په هغوئ هر يو نازلې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25826, 'Acts 2:4', 'Acts', 2, 4, '&nbsp;او هغوئ ټول د روحُ القُدس نه معمور شول او په نورو ژبو يې خبرې شروع کړې څنګه چې روحُ القُدس د خبرو طاقت ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25827, 'Acts 2:5', 'Acts', 2, 5, '&nbsp;هغه وخت په يروشلم کښې د آسمان د لاندې د هر قوم نه راغلى پرهيزګاره يهوديان اوسېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25828, 'Acts 2:6', 'Acts', 2, 6, '&nbsp;کله چې هغوئ دا آواز واورېدلو نو ګڼه راجمع شوه او هغوئ په دې حېران شول ځکه چې هغوئ هر يو په خپله خپله ژبه د هغوئ نه خبرې اورېدلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25829, 'Acts 2:7', 'Acts', 2, 7, '&nbsp;په سختې حېرانتيا سره هغوئ تپوس وکړو چې، ”دا ټول ګليليان نۀ دى چې خبرې کوى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25830, 'Acts 2:8', 'Acts', 2, 8, '&nbsp;نو بيا دا څنګه کېدے شى چې مونږ هر يو د هغوئ نه زمونږ په مورنۍ ژبه خبرې اورو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25831, 'Acts 2:9', 'Acts', 2, 9, '&nbsp;يعنې پارتهيان، ميديان، عيلاميان، او د مسوپتاميه اوسېدونکى، د يهوديه، کپدوکيه، پونطوس، آسيه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25832, 'Acts 2:10', 'Acts', 2, 10, '&nbsp;فروګيه، پمفوليه، مِصر، ليبيا د ضلعو چې د کرينى طرف ته دى او هم رومى مسافران،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25833, 'Acts 2:11', 'Acts', 2, 11, '&nbsp;يهوديان او نوې يهوديان شوى دواړه، کريتيان او عرب، مونږ ټول اورو چې هغوئ د خُدائ پاک لوئ کارونه زمونږ په خپلو ژبو کښې بيانوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25834, 'Acts 2:12', 'Acts', 2, 12, '&nbsp;هغوئ ټول حېران او پرېشانه وُو او يو بل ته يې ووئيل چې، ”د دې څۀ مطلب دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25835, 'Acts 2:13', 'Acts', 2, 13, '&nbsp;خو ځينو په هغوئ پورې ټوقې وکړې او وئ وئيل چې، ”دوئ د شرابو په نشه کښې دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25836, 'Acts 2:14', 'Acts', 2, 14, '&nbsp;بيا پطروس د نورو يوولسو تنو سره پاڅېدو او په اوچت آواز يې ګڼې ته بيان وکړو، ”اے يهوديانو ملګرو او د يروشلم اوسېدونکو، څۀ چې زۀ وايم هغه غور سره واورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25837, 'Acts 2:15', 'Acts', 2, 15, '&nbsp;دا کسان د شرابو په نشه کښې نۀ دى لکه څنګه چې ستاسو خيال دے ځکه چې اوس خو لا د سحر نهۀ بجې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25838, 'Acts 2:16', 'Acts', 2, 16, '&nbsp;خو دا هغه څۀ دى چې يوايل نبى د هغې په حقله وئيلى وُو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25839, 'Acts 2:17', 'Acts', 2, 17, '&nbsp;خُدائ پاک فرمائى، د دې ټولو کارونو کولو نه وروستو به زۀ خپل روح په ټولو خلقو نازل کړم. ستاسو زامن او لوڼه به نبوت کوى. ستاسو مشران به خوبونه وينى، او ستاسو ځوانان به رويا ګانې وينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25840, 'Acts 2:18', 'Acts', 2, 18, '&nbsp;تر دې چې زۀ به په هغه ورځو کښې په خپلو نوکرانو سړو او ښځو دواړو خپل روح هم نازل کړم او هغوئ به نبوت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25841, 'Acts 2:19', 'Acts', 2, 19, '&nbsp;او زۀ به په آسمانونو او زمکه کښې حېرانونکى نښې يعنې وينه، اور او د لوګى برجۍ ښکاره کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25842, 'Acts 2:20', 'Acts', 2, 20, '&nbsp;نمر به تور شى، او سپوږمۍ به لکه د وينو تکه سره شى مخکښې د دې نه چې د مالِک خُدائ د قيامت هغه لويه او هيبتناکه ورځ راورسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25843, 'Acts 2:21', 'Acts', 2, 21, '&nbsp;خو څوک چې د مالِک خُدائ په نوم مدد وغواړى هغه به بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25844, 'Acts 2:22', 'Acts', 2, 22, '&nbsp;اے د بنى اِسرائيلو خلقو، دا خبرې واورئ چې، عيسىٰ ناصرى يو سړے وو چې خُدائ پاک تاسو ته په معجزو او په عجيبه کارونو او نښو سره د هغۀ تصديق وکړو، کومې چې خُدائ پاک د هغۀ په وسيله ستاسو په مينځ کښې وکړې، لکه څنګه چې تاسو ته په خپله پته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25845, 'Acts 2:23', 'Acts', 2, 23, '&nbsp;دا سړے د خُدائ پاک د خاص منصوبې او د پوهې په مطابق تاسو ته حواله کړے شو او تاسو هغه د بې‌دينه خلقو په وسيله په سولۍ وخېژولو او مړ مو کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25846, 'Acts 2:24', 'Acts', 2, 24, '&nbsp;خو خُدائ پاک هغه بيا راژوندے کړو او د مرګ د تکليفونو نه يې خلاص کړو ځکه چې د دې امکان نۀ وو چې مرګ په هغۀ قبضه وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25847, 'Acts 2:25', 'Acts', 2, 25, '&nbsp;حضرت داؤد د هغۀ په حقله فرمائى چې، ”زۀ په دې پوهېږم مالِک خُدائ همېشه راسره دے. هغه ما سره په خوا کښې دے نو زۀ به نۀ غورزېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25848, 'Acts 2:26', 'Acts', 2, 26, '&nbsp;نو ځکه مې زړۀ خوشحاله دے خوشحالېږم، ژوند کوم او په امان کښې اوسېږم، په دې وجه زما زړۀ خوشحاله دے او زما ژبه خوشحالى کوى، بلکې زما بدن به هم په اُميد کښې اوسى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
